  constructor(container, content) {
    const width = container.offsetWidth;
    const font = window.getComputedStyle(container).font;
    const textWidth = getTextWidth(content, font);

    if (textWidth > width) {
      const text = content.repeat(2);
      container.innerHTML = `<div>${text}</div>`;
    } else {
      container.innerHTML = `<div>${content}</div>`;
    }

    container.style.overflow = 'hidden';
    container.style.whiteSpace = 'nowrap';

    this.animationContainer = container.firstElementChild;
    this.textWidth = textWidth;
    this.useAniation = textWidth > width;
  }

  start() {
    if (!this.useAniation) {
      return;
    }
    this.animation = this.animationContainer.animate([{
      transform: 'translateX(0)',
      offset: 0
    }, {
      transform: 'translateX(-' + this.textWidth + 'px)',
      offset: 1
    }], {
      duration: 3000,
      iterations: Infinity,
    })
  }

  pause() {
    if (!this.useAniation) {
      return;
    }
    this.animation.pause();
  }

  resume() {
    if (!this.useAniation) {
      return;
    }
    this.animation.play();
  }

  speedUp() {
    if (!this.useAniation) {
      return;
    }
    this.animation.playbackRate = this.animation.playbackRate * 2;
  }

  slowDown() {
    if (!this.useAniation) {
      return;
    }
    this.animation.playbackRate = this.animation.playbackRate / 2;
  }
}
